@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? toastMessage;
    private string toastType = "success";
    private System.Timers.Timer? toastTimer;

    // Profile state
    private ProfileEditModel? editProfile;
    private UserProfile? savedProfile;

    // Notifications state
    private NotificationEditModel? editNotifications;
    private List<string> availableChannels = new() { "General", "Updates", "Marketing", "Support", "Engineering" };

    // Security state
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string currentSessionId = "session-1";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance state
    private AppearanceEditModel? editAppearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadSection("Profile");
        isLoading = false;
    }

    private async Task SetSection(string section)
    {
        if (activeSection == section) return;
        activeSection = section;
        isLoading = true;
        await LoadSection(section);
        isLoading = false;
    }

    private async Task LoadSection(string section)
    {
        switch (section)
        {
            case "Profile":
                savedProfile = await SettingsService.GetProfileAsync();
                editProfile = new ProfileEditModel(savedProfile);
                break;
            case "Notifications":
                var notifPrefs = await SettingsService.GetNotificationPrefsAsync();
                editNotifications = new NotificationEditModel(notifPrefs);
                break;
            case "Security":
                securitySettings = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                editAppearance = new AppearanceEditModel(appearance);
                break;
        }
    }

    // ==================== Profile Methods ====================

    private async Task SaveProfile()
    {
        var profile = new UserProfile(
            editProfile!.DisplayName,
            editProfile.Email,
            editProfile.AvatarUrl,
            editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        editProfile = new ProfileEditModel(savedProfile!);
        ShowToast("Changes discarded.", "info");
    }

    // ==================== Notifications Methods ====================

    private void ToggleMuteChannel(string channel, bool isMuted)
    {
        if (isMuted && !editNotifications!.MutedChannels.Contains(channel))
            editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            editNotifications!.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            editNotifications!.EmailNotifications,
            editNotifications.PushNotifications,
            editNotifications.WeeklyDigest,
            new List<string>(editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // ==================== Security Methods ====================

    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("New password cannot be empty.", "error");
            return;
        }

        if (newPassword != confirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast($"Session on {sessionToRevoke.Device} revoked.", "success");
        }
        CancelRevoke();
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // ==================== Appearance Methods ====================

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{editAppearance!.Theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{editAppearance.FontSize.ToLowerInvariant()}");
        if (editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(
            editAppearance!.Theme,
            editAppearance.FontSize,
            editAppearance.Language,
            editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // ==================== Toast ====================

    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        toastTimer?.Dispose();
        toastTimer = new System.Timers.Timer(3000);
        toastTimer.Elapsed += (_, _) =>
        {
            toastMessage = null;
            toastTimer?.Dispose();
            InvokeAsync(StateHasChanged);
        };
        toastTimer.AutoReset = false;
        toastTimer.Start();
    }

    public void Dispose()
    {
        toastTimer?.Dispose();
    }

    // ==================== Edit Models ====================

    private class ProfileEditModel
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public ProfileEditModel(UserProfile profile)
        {
            DisplayName = profile.DisplayName;
            Email = profile.Email;
            AvatarUrl = profile.AvatarUrl;
            Bio = profile.Bio;
        }
    }

    private class NotificationEditModel
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; }

        public NotificationEditModel(NotificationPrefs prefs)
        {
