+
+.toast.error {
+    background: #d93025;
+    color: white;
+}
+
+.toast.info {
+    background: #1a73e8;
+    color: white;
+}
+
+@keyframes slideIn {
+    from {
+        transform: translateX(100%);
+        opacity: 0;
+    }
+    to {
+        transform: translateX(0);
+        opacity: 1;
+    }
+}
+
+/* Loading */
+.loading-spinner {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    padding: 3rem;
+    color: #666;
+    font-size: 1rem;
+}
